export type OrderStatus = 'Baru' | 'Proses' | 'Selesai';

export type ServiceType = 'Cuci Kering' | 'Cuci Setrika' | 'Setrika Saja';

export const SERVICE_PRICES: Record<ServiceType, number> = {
  'Cuci Kering': 5000,
  'Cuci Setrika': 7000,
  'Setrika Saja': 4000,
};

export interface Order {
  id: string;
  notaNumber: string;
  customerName: string;
  customerPhone: string;
  customerAddress: string;
  weight: number;
  serviceType: ServiceType;
  totalPrice: number;
  status: OrderStatus;
  createdAt: string;
  estimatedFinishDate: string;
  specialRequest?: string;
  deliveryMethod: 'Antar/Jemput' | 'Ambil Sendiri';
}

export type Role = 'ADMIN' | 'CUSTOMER';

export const formatIDR = (amount: number): string => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency',
    currency: 'IDR',
    minimumFractionDigits: 0,
  }).format(amount);
};

export const generateNotaNumber = (): string => {
  const date = new Date();
  const year = date.getFullYear().toString().slice(-2);
  const month = (date.getMonth() + 1).toString().padStart(2, '0');
  const random = Math.floor(Math.random() * 9000 + 1000);
  return `TINI-${year}${month}-${random}`;
};

export const playNotificationSound = () => {
  const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();

  const playTone = (freq: number, start: number, duration: number) => {
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, start);

    gain.gain.setValueAtTime(0, start);
    gain.gain.linearRampToValueAtTime(0.2, start + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, start + duration);

    osc.connect(gain);
    gain.connect(audioCtx.destination);

    osc.start(start);
    osc.stop(start + duration);
  };

  // Play a pleasant double-ping
  playTone(880, audioCtx.currentTime, 0.5);
  playTone(1108.73, audioCtx.currentTime + 0.1, 0.5);
};

export const sendWhatsAppMessage = (phone: string, message: string) => {
  const cleanPhone = phone.replace(/[^0-9]/g, '');
  const formattedPhone = cleanPhone.startsWith('0') ? '62' + cleanPhone.slice(1) : cleanPhone;
  const url = `https://wa.me/${formattedPhone}?text=${encodeURIComponent(message)}`;
  window.open(url, '_blank');
};

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error("Could not find root element");

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  PlusCircle, 
  Search, 
  ShoppingBag, 
  UserCircle, 
  Settings, 
  LogOut, 
  CheckCircle2, 
  Clock, 
  Package, 
  ArrowRight,
  Phone,
  FileText,
  TrendingUp,
  Moon,
  Sun,
  X,
  Printer,
  ChevronRight,
  ClipboardList
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  AreaChart, 
  Area 
} from 'recharts';
import { 
  Order, 
  Role, 
  OrderStatus, 
  ServiceType, 
  SERVICE_PRICES 
} from './types';
import { 
  formatIDR, 
  generateNotaNumber, 
  playNotificationSound, 
  sendWhatsAppMessage 
} from './utils';

// --- Shared Components ---

const Button = ({ children, onClick, variant = 'primary', className = '', type = 'button', disabled = false }: any) => {
  const variants = {
    primary: 'bg-blue-600 text-white hover:bg-blue-700',
    secondary: 'bg-gray-100 text-gray-700 hover:bg-gray-200',
    success: 'bg-green-600 text-white hover:bg-green-700',
    danger: 'bg-red-600 text-white hover:bg-red-700',
    outline: 'border-2 border-blue-600 text-blue-600 hover:bg-blue-50'
  };
  return (
    <button
      type={type}
      disabled={disabled}
      onClick={onClick}
      className={`px-4 py-2 rounded-xl font-semibold transition-all duration-200 active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2 ${variants[variant as keyof typeof variants]} ${className}`}
    >
      {children}
    </button>
  );
};

const Card = ({ children, className = "" }: { children: React.ReactNode; className?: string }) => (
  <div className={`bg-white rounded-2xl shadow-sm border border-gray-100 p-6 ${className}`}>
    {children}
  </div>
);

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'info', onClose: () => void }) => (
  <div className={`fixed top-4 right-4 z-[100] p-4 rounded-xl shadow-lg border flex items-center gap-3 animate-slide-in-right ${type === 'success' ? 'bg-green-50 border-green-200 text-green-800' : 'bg-blue-50 border-blue-200 text-blue-800'}`}>
    {type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <Clock className="w-5 h-5" />}
    <p className="font-medium">{message}</p>
    <button onClick={onClose} className="p-1 hover:bg-black/5 rounded-full"><X className="w-4 h-4" /></button>
  </div>
);

// --- Main App Component ---

export default function App() {
  const [role, setRole] = useState<Role | null>(null);
  const [orders, setOrders] = useState<Order[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showSplash, setShowSplash] = useState(true);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'orders' | 'add'>('dashboard');
  const [searchQuery, setSearchQuery] = useState('');
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'info' } | null>(null);

  // Persistence
  useEffect(() => {
    const savedOrders = localStorage.getItem('tini_orders');
    if (savedOrders) setOrders(JSON.parse(savedOrders));

    const timer = setTimeout(() => setShowSplash(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    localStorage.setItem('tini_orders', JSON.stringify(orders));
  }, [orders]);

  const addOrder = (newOrder: Order, notify: boolean = true) => {
    setOrders(prev => [newOrder, ...prev]);
    if (notify) {
      playNotificationSound();
      setToast({ message: `Order baru dari ${newOrder.customerName} diterima!`, type: 'info' });
      setTimeout(() => setToast(null), 5000);
    }
  };

  const updateOrderStatus = (id: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === id ? { ...o, status: newStatus } : o));
    setToast({ message: 'Status order diperbarui!', type: 'success' });
    setTimeout(() => setToast(null), 3000);
  };

  // Stats for Dashboard
  const stats = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const monthlyOrders = orders.filter(o => {
      const d = new Date(o.createdAt);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const omzet = monthlyOrders.reduce((acc, curr) => acc + curr.totalPrice, 0);
    const completed = monthlyOrders.filter(o => o.status === 'Selesai').length;
    const process = monthlyOrders.filter(o => o.status === 'Proses').length;

    // Simple revenue data for chart
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - (6 - i));
      const dateStr = d.toLocaleDateString('id-ID', { weekday: 'short' });
      const dayTotal = orders
        .filter(o => new Date(o.createdAt).toDateString() === d.toDateString())
        .reduce((sum, o) => sum + o.totalPrice, 0);
      return { name: dateStr, revenue: dayTotal };
    });

    return { omzet, completed, process, chartData: last7Days };
  }, [orders]);

  if (showSplash) {
    return (
      <div className="fixed inset-0 bg-blue-600 flex flex-items-center justify-center flex-col text-white">
        <div className="w-32 h-32 bg-white rounded-full flex items-center justify-center mb-6 animate-bounce shadow-2xl">
          <ShoppingBag className="w-16 h-16 text-blue-600" />
        </div>
        <h1 className="text-3xl font-bold tracking-tight">LAUNDRY IBU TINI</h1>
        <p className="mt-2 text-blue-100">Bersih • Wangi • Rapi</p>
      </div>
    );
  }

  if (!role) {
    return (
      <div className="min-h-screen bg-blue-50 flex items-center justify-center p-6">
        <div className="max-w-md w-full">
          <Card className="text-center py-10">
            <h2 className="text-2xl font-bold mb-2">Selamat Datang!</h2>
            <p className="text-gray-500 mb-8">Pilih akses masuk Anda ke sistem Laundry Ibu Tini</p>
            <div className="space-y-4">
              <button 
                onClick={() => setRole('ADMIN')}
                className="w-full flex items-center justify-between p-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl transition-all group"
              >
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-white/20 rounded-xl">
                    <Settings className="w-6 h-6" />
                  </div>
                  <div className="text-left">
                    <p className="font-bold">Akses Admin</p>
                    <p className="text-xs text-blue-100">Kelola order & laporan</p>
                  </div>
                </div>
                <ChevronRight className="group-hover:translate-x-1 transition-transform" />
              </button>

              <button 
                onClick={() => setRole('CUSTOMER')}
                className="w-full flex items-center justify-between p-4 bg-white border-2 border-blue-600 hover:bg-blue-50 text-blue-600 rounded-2xl transition-all group"
              >
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-blue-100 rounded-xl">
                    <UserCircle className="w-6 h-6" />
                  </div>
                  <div className="text-left">
                    <p className="font-bold">Akses Pelanggan</p>
                    <p className="text-xs text-blue-500">Order & cek status laundry</p>
                  </div>
                </div>
                <ChevronRight className="group-hover:translate-x-1 transition-transform" />
              </button>
            </div>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${isDarkMode ? 'dark bg-gray-900 text-white' : 'bg-gray-50'}`}>
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      {/* Sidebar - Desktop Only */}
      <div className="hidden md:fixed md:inset-y-0 md:flex md:w-64 md:flex-col">
        <div className="flex min-h-0 flex-1 flex-col bg-blue-700">
          <div className="flex flex-1 flex-col overflow-y-auto pt-5 pb-4">
            <div className="flex flex-shrink-0 items-center px-4 gap-3 text-white">
              <div className="bg-white p-2 rounded-lg">
                <ShoppingBag className="w-6 h-6 text-blue-700" />
              </div>
              <span className="font-bold text-xl uppercase tracking-wider">Ibu Tini</span>
            </div>
            <nav className="mt-8 flex-1 space-y-2 px-2">
              {role === 'ADMIN' ? (
                <>
                  <SidebarLink icon={LayoutDashboard} label="Dashboard" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />
                  <SidebarLink icon={ClipboardList} label="Data Order" active={activeTab === 'orders'} onClick={() => setActiveTab('orders')} />
                  <SidebarLink icon={PlusCircle} label="Tambah Order" active={activeTab === 'add'} onClick={() => setActiveTab('add')} />
                </>
              ) : (
                <>
                  <SidebarLink icon={PlusCircle} label="Order Baru" active={activeTab === 'add'} onClick={() => setActiveTab('add')} />
                  <SidebarLink icon={Search} label="Cek Status" active={activeTab === 'orders'} onClick={() => setActiveTab('orders')} />
                </>
              )}
            </nav>
          </div>
          <div className="flex flex-shrink-0 bg-blue-800 p-4">
            <button onClick={() => setRole(null)} className="flex items-center gap-3 text-white/80 hover:text-white font-medium">
              <LogOut className="w-5 h-5" /> Keluar Sistem
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="md:pl-64 flex flex-col flex-1">
        <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-md border-b px-4 py-4 flex items-center justify-between">
          <div className="md:hidden flex items-center gap-2">
            <ShoppingBag className="text-blue-600" />
            <span className="font-bold text-lg">Laundry Ibu Tini</span>
          </div>
          <h2 className="hidden md:block text-xl font-bold text-gray-800">
            {role === 'ADMIN' ? 'Portal Admin' : 'Portal Pelanggan'}
          </h2>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 hover:bg-gray-100 rounded-full">
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold">
                {role === 'ADMIN' ? 'A' : 'P'}
              </div>
            </div>
          </div>
        </header>

        <main className="p-4 md:p-8 max-w-7xl mx-auto w-full">
          {activeTab === 'dashboard' && role === 'ADMIN' && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <StatCard label="Total Omzet Bulan Ini" value={formatIDR(stats.omzet)} icon={TrendingUp} color="blue" />
                <StatCard label="Order Selesai" value={stats.completed} icon={CheckCircle2} color="green" />
                <StatCard label="Sedang Diproses" value={stats.process} icon={Clock} color="orange" />
                <StatCard label="Total Order" value={orders.length} icon={Package} color="purple" />
              </div>

              <Card className="h-[400px]">
                <h3 className="text-lg font-bold mb-4">Grafik Pendapatan (7 Hari Terakhir)</h3>
                <ResponsiveContainer width="100%" height="90%">
                  <AreaChart data={stats.chartData}>
                    <defs>
                      <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#2563eb" stopOpacity={0.1}/>
                        <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="name" />
                    <YAxis tickFormatter={(val) => `Rp${val/1000}k`} />
                    <Tooltip formatter={(val: number) => formatIDR(val)} />
                    <Area type="monotone" dataKey="revenue" stroke="#2563eb" fillOpacity={1} fill="url(#colorRevenue)" strokeWidth={2} />
                  </AreaChart>
                </ResponsiveContainer>
              </Card>
            </div>
          )}

          {activeTab === 'add' && (
            <OrderForm role={role} onAdd={addOrder} />
          )}

          {activeTab === 'orders' && (
            <div className="space-y-6">
              <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
                <div className="relative w-full md:w-96">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                  <input 
                    type="text" 
                    placeholder="Cari Nama Pelanggan atau No Nota..." 
                    className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                  />
                </div>
                <div className="flex items-center gap-2 overflow-x-auto w-full md:w-auto">
                   <StatusFilter current="Semua" onClick={() => {}} />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {orders
                  .filter(o => 
                    o.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || 
                    o.notaNumber.toLowerCase().includes(searchQuery.toLowerCase())
                  )
                  .map(order => (
                    <OrderCard 
                      key={order.id} 
                      order={order} 
                      isAdmin={role === 'ADMIN'} 
                      onUpdateStatus={updateOrderStatus}
                    />
                  ))
                }
                {orders.length === 0 && (
                  <div className="col-span-full py-20 text-center">
                    <Package className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                    <h3 className="text-xl font-medium text-gray-500">Belum ada order laundry</h3>
                    <Button variant="outline" className="mt-4" onClick={() => setActiveTab('add')}>Tambah Order Pertama</Button>
                  </div>
                )}
              </div>
            </div>
          )}
        </main>
      </div>

      {/* Floating WA Button */}
      <a 
        href="https://wa.me/085695014434" 
        target="_blank" 
        className="whatsapp-float"
        title="Hubungi Admin WA"
      >
        <Phone />
      </a>

      {/* Mobile Navigation */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t flex justify-around p-3 pb-6 z-50">
        <MobileNavButton icon={LayoutDashboard} active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />
        <MobileNavButton icon={ClipboardList} active={activeTab === 'orders'} onClick={() => setActiveTab('orders')} />
        <MobileNavButton icon={PlusCircle} active={activeTab === 'add'} onClick={() => setActiveTab('add')} />
        <MobileNavButton icon={LogOut} active={false} onClick={() => setRole(null)} />
      </div>
    </div>
  );
}

// --- Sub-components ---

function SidebarLink({ icon: Icon, label, active, onClick }: any) {
  return (
    <button
      onClick={onClick}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 ${
        active ? 'bg-white text-blue-700 font-bold shadow-md' : 'text-blue-100 hover:bg-white/10'
      }`}
    >
      <Icon className="w-5 h-5" />
      <span>{label}</span>
    </button>
  );
}

function MobileNavButton({ icon: Icon, active, onClick }: any) {
  return (
    <button onClick={onClick} className={`p-2 rounded-xl ${active ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>
      <Icon className="w-6 h-6" />
    </button>
  );
}

function StatCard({ label, value, icon: Icon, color }: any) {
  const colors = {
    blue: 'bg-blue-50 text-blue-600',
    green: 'bg-green-50 text-green-600',
    orange: 'bg-orange-50 text-orange-600',
    purple: 'bg-purple-50 text-purple-600'
  };
  return (
    <Card className="flex items-center gap-4">
      <div className={`p-4 rounded-2xl ${colors[color as keyof typeof colors]}`}>
        <Icon className="w-6 h-6" />
      </div>
      <div>
        <p className="text-sm text-gray-500 font-medium">{label}</p>
        <p className="text-2xl font-bold">{value}</p>
      </div>
    </Card>
  );
}

function StatusFilter({ current, onClick }: any) {
  return (
    <button onClick={onClick} className={`px-4 py-1.5 rounded-full text-sm font-semibold border ${current ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white text-gray-600 border-gray-200'}`}>
      {current}
    </button>
  );
}

function OrderForm({ role, onAdd }: { role: Role, onAdd: (o: Order, n: boolean) => void }) {
  const [formData, setFormData] = useState({
    customerName: '',
    customerPhone: '',
    customerAddress: '',
    weight: 0,
    serviceType: 'Cuci Kering' as ServiceType,
    specialRequest: '',
    deliveryMethod: 'Ambil Sendiri' as any
  });

  const total = formData.weight * SERVICE_PRICES[formData.serviceType];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newOrder: Order = {
      id: Date.now().toString(),
      notaNumber: generateNotaNumber(),
      ...formData,
      totalPrice: total,
      status: 'Baru',
      createdAt: new Date().toISOString(),
      estimatedFinishDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString(),
    };

    onAdd(newOrder, role === 'ADMIN'); // Notify admin if admin added it, or notify if system added it via customer form

    // Auto WhatsApp Message as requested
    const waMessage = `Halo 👋 Terima kasih Kak 🙏
Laundry atas nama ${newOrder.customerName} sudah kami terima.
Layanan: ${newOrder.serviceType}
Berat: ${newOrder.weight}kg
Total sementara: ${formatIDR(newOrder.totalPrice)}
Estimasi selesai: 2 hari.
Kami akan kabari saat sudah selesai ya 😊`;

    sendWhatsAppMessage(newOrder.customerPhone, waMessage);

    // Reset
    setFormData({
      customerName: '',
      customerPhone: '',
      customerAddress: '',
      weight: 0,
      serviceType: 'Cuci Kering',
      specialRequest: '',
      deliveryMethod: 'Ambil Sendiri'
    });
  };

  return (
    <div className="max-w-2xl mx-auto">
      <Card>
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-blue-100 rounded-lg">
            <PlusCircle className="text-blue-600" />
          </div>
          <h3 className="text-xl font-bold">Input Order Laundry</h3>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-semibold mb-1 text-gray-700">Nama Pelanggan</label>
              <input 
                required
                type="text" 
                className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                placeholder="Ex: Budi Santoso"
                value={formData.customerName}
                onChange={(e) => setFormData({...formData, customerName: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-semibold mb-1 text-gray-700">Nomor HP (WhatsApp)</label>
              <input 
                required
                type="tel" 
                className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                placeholder="Ex: 08123456789"
                value={formData.customerPhone}
                onChange={(e) => setFormData({...formData, customerPhone: e.target.value})}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-semibold mb-1 text-gray-700">Alamat</label>
            <input 
              required
              type="text" 
              className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="Ex: Jl. Melati No. 5"
              value={formData.customerAddress}
              onChange={(e) => setFormData({...formData, customerAddress: e.target.value})}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-semibold mb-1 text-gray-700">Berat (Kg)</label>
              <input 
                required
                type="number" 
                min="0.5"
                step="0.1"
                className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.weight}
                onChange={(e) => setFormData({...formData, weight: parseFloat(e.target.value) || 0})}
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-semibold mb-1 text-gray-700">Pilih Layanan</label>
              <select 
                className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.serviceType}
                onChange={(e) => setFormData({...formData, serviceType: e.target.value as ServiceType})}
