              <div className="flex gap-2">
                {['Ambil Sendiri', 'Antar/Jemput'].map(m => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setFormData({...formData, deliveryMethod: m as any})}
                    className={`flex-1 py-2 px-3 rounded-xl border-2 transition-all font-medium text-sm ${formData.deliveryMethod === m ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-gray-200 text-gray-500'}`}
