          <ShoppingBag className="w-16 h-16 text-blue-600" />
        </div>
        <h1 className="text-3xl font-bold tracking-tight">LAUNDRY IBU TINI</h1>
        <p className="mt-2 text-blue-100">Bersih • Wangi • Rapi</p>
      </div>
    );
  }

  if (!role) {
    return (
      <div className="min-h-screen bg-blue-50 flex items-center justify-center p-6 relative">
        <div className="max-w-md w-full">
          <Card className="text-center py-10">
            <h2 className="text-2xl font-bold mb-2">Selamat Datang!</h2>
            <p className="text-gray-500 mb-8">Pilih akses masuk Anda ke sistem Laundry Ibu Tini</p>
