                    <Settings className="w-6 h-6" />
                  </div>
                  <div className="text-left">
                    <p className="font-bold">Akses Admin</p>
                    <p className="text-xs text-blue-100">Kelola order & laporan</p>
                  </div>
                </div>
                <ChevronRight className="group-hover:translate-x-1 transition-transform" />
              </button>

              <button 
                onClick={() => {
                  setRole('CUSTOMER');
                  setActiveTab('add');
                }}
                className="w-full flex items-center justify-between p-4 bg-white border-2 border-blue-600 hover:bg-blue-50 text-blue-600 rounded-2xl transition-all group"
              >
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-blue-100 rounded-xl">
                    <UserCircle className="w-6 h-6" />
                  </div>
                  <div className="text-left">
                    <p className="font-bold">Akses Pelanggan</p>
