function OrderCard({ order, isAdmin, onUpdateStatus }: { order: Order, isAdmin: boolean, onUpdateStatus: (id: string, s: OrderStatus) => void }) {

  const generatePDF = async () => {
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: [80, 150] 
    });

    const margin = 5;
    const pageWidth = 80;
    let y = 10;

    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text("LAUNDRY IBU TINI", pageWidth / 2, y, { align: "center" });
    y += 5;
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text("Bersih • Wangi • Rapi", pageWidth / 2, y, { align: "center" });
    y += 5;
    doc.text("==============================", pageWidth / 2, y, { align: "center" });
    y += 7;

    const drawLine = (label: string, value: string) => {
      doc.text(label, margin, y);
      doc.text(value, pageWidth - margin, y, { align: "right" });
      y += 5;
    };

    doc.setFont("helvetica", "bold");
    drawLine("No Nota:", order.notaNumber);
    doc.setFont("helvetica", "normal");
    drawLine("Tanggal:", new Date(order.createdAt).toLocaleDateString());
    drawLine("Nama:", order.customerName);
    drawLine("Telepon:", order.customerPhone);
    y += 2;
    doc.text("------------------------------", pageWidth / 2, y, { align: "center" });
    y += 5;
    drawLine("Layanan:", order.serviceType);
    drawLine("Berat:", `${order.weight} Kg`);
    drawLine("Harga/kg:", formatIDR(SERVICE_PRICES[order.serviceType]));
    y += 2;
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    drawLine("TOTAL:", formatIDR(order.totalPrice));
    y += 5;
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    drawLine("Estimasi Selesai:", new Date(order.estimatedFinishDate).toLocaleDateString());
    y += 10;
    doc.text("Terima kasih telah", pageWidth / 2, y, { align: "center" });
    y += 4;
    doc.text("menggunakan jasa kami 🙏", pageWidth / 2, y, { align: "center" });

    doc.save(`Nota_${order.notaNumber}.pdf`);
  };

  const handleFinishNotify = () => {
    const msg = `Halo Kak 👋
Laundry atas nama ${order.customerName} sudah SELESAI ✅
Total pembayaran: ${formatIDR(order.totalPrice)}
Bisa diambil atau kami antar ya 🚚😊`;
    sendWhatsAppMessage(order.customerPhone, msg);
    onUpdateStatus(order.id, 'Selesai');
  };

  const statusColors = {
    'Baru': 'bg-blue-100 text-blue-700',
    'Proses': 'bg-orange-100 text-orange-700',
    'Selesai': 'bg-green-100 text-green-700'
  };

  return (
    <Card className="hover:shadow-md transition-shadow relative">
      <div className="flex justify-between items-start mb-4">
        <div>
          <p className="text-xs font-bold text-gray-400 uppercase tracking-tighter">{order.notaNumber}</p>
          <h4 className="text-lg font-bold text-gray-800">{order.customerName}</h4>
        </div>
        <span className={`px-3 py-1 rounded-full text-xs font-bold ${statusColors[order.status]}`}>
          {order.status}
        </span>
      </div>

      <div className="space-y-2 mb-6">
        <div className="flex items-center gap-2 text-sm text-gray-600">
          <Package className="w-4 h-4" />
          <span>{order.serviceType} • {order.weight}kg</span>
        </div>
        <div className="flex items-center gap-2 text-sm text-gray-600">
          <Clock className="w-4 h-4" />
          <span>Selesai: {new Date(order.estimatedFinishDate).toLocaleDateString()}</span>
        </div>
        <div className="flex items-center gap-2 text-sm text-gray-600">
          <Phone className="w-4 h-4" />
          <span>{order.customerPhone}</span>
        </div>
      </div>

      <div className="pt-4 border-t border-gray-100 flex items-center justify-between mb-4">
        <p className="text-sm text-gray-500 font-medium">Tagihan</p>
        <p className="text-xl font-bold text-blue-600">{formatIDR(order.totalPrice)}</p>
      </div>

      <div className="grid grid-cols-2 gap-2">
        <button 
          onClick={generatePDF}
          className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 p-2 rounded-xl transition-all"
        >
          <Printer className="w-4 h-4" /> Nota
        </button>

        {isAdmin && (
          <>
            {order.status === 'Baru' && (
              <button 
                onClick={() => onUpdateStatus(order.id, 'Proses')}
                className="bg-orange-600 hover:bg-orange-700 text-white p-2 rounded-xl transition-all font-semibold"
              >
                Proses
              </button>
            )}
            {order.status === 'Proses' && (
              <button 
                onClick={handleFinishNotify}
                className="bg-green-600 hover:bg-green-700 text-white p-2 rounded-xl transition-all font-semibold"
              >
                Selesaikan
              </button>
            )}
            {order.status === 'Selesai' && (
              <div className="flex items-center justify-center gap-1 text-green-600 font-bold text-sm">
                <CheckCircle2 className="w-4 h-4" /> Selesai
              </div>
            )}
          </>
        )}
      </div>
    </Card>
  );
}

