            {role === 'ADMIN' ? 'Portal Admin' : 'Pesanan Saya'}
          </h2>
          <div className="flex items-center gap-4">
            {role === 'CUSTOMER' && (
              <div className="hidden lg:flex items-center gap-2 px-3 py-1 bg-blue-50 text-blue-700 rounded-full text-sm font-medium">
                <Phone className="w-4 h-4" /> {customerPhone}
              </div>
            )}
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 hover:bg-gray-100 rounded-full">
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold">
                {role === 'ADMIN' ? 'A' : 'P'}
              </div>
            </div>
          </div>
        </header>

        <main className="p-4 md:p-8 max-w-7xl mx-auto w-full pb-24">
          {activeTab === 'dashboard' && role === 'ADMIN' && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <StatCard label="Total Omzet Bulan Ini" value={formatIDR(stats.omzet)} icon={TrendingUp} color="blue" />
                <StatCard label="Order Selesai" value={stats.completed} icon={CheckCircle2} color="green" />
                <StatCard label="Sedang Diproses" value={stats.process} icon={Clock} color="orange" />
                <StatCard label="Total Order" value={orders.length} icon={Package} color="purple" />
              </div>

              <Card className="h-[400px]">
                <h3 className="text-lg font-bold mb-4">Grafik Pendapatan (7 Hari Terakhir)</h3>
                <ResponsiveContainer width="100%" height="90%">
                  <AreaChart data={stats.chartData}>
                    <defs>
                      <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#2563eb" stopOpacity={0.1}/>
                        <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="name" />
                    <YAxis tickFormatter={(val) => `Rp${val/1000}k`} />
                    <Tooltip formatter={(val: number) => formatIDR(val)} />
                    <Area type="monotone" dataKey="revenue" stroke="#2563eb" fillOpacity={1} fill="url(#colorRevenue)" strokeWidth={2} />
                  </AreaChart>
                </ResponsiveContainer>
              </Card>
            </div>
          )}

          {activeTab === 'add' && (
            <OrderForm role={role} prefilledPhone={customerPhone} onAdd={addOrder} />
          )}

          {activeTab === 'orders' && (
            <div className="space-y-6">
              <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
                <div className="relative w-full md:w-96">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                  <input 
                    type="text" 
                    placeholder={role === 'ADMIN' ? "Cari Nama, No Nota, atau HP..." : "Cari No Nota..."}
                    className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                  />
                </div>
                <div className="flex items-center gap-2 overflow-x-auto w-full md:w-auto">
                   <StatusFilter current="Semua" onClick={() => {}} />
                </div>
              </div>

              {role === 'CUSTOMER' && filteredOrders.length > 0 && (
                <div className="bg-blue-50 border border-blue-100 p-4 rounded-xl flex items-center gap-3">
                  <div className="p-2 bg-blue-100 rounded-full text-blue-600">
                    <UserCircle className="w-5 h-5" />
                  </div>
                  <div>
                    <p className="text-sm font-bold text-blue-800">Riwayat untuk {customerPhone}</p>
                    <p className="text-xs text-blue-600">Ditemukan {filteredOrders.length} pesanan</p>
                  </div>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {filteredOrders.map(order => (
                  <OrderCard 
                    key={order.id} 
                    order={order} 
                    isAdmin={role === 'ADMIN'} 
                    onUpdateStatus={updateOrderStatus}
                  />
                ))}
                {filteredOrders.length === 0 && (
                  <div className="col-span-full py-20 text-center">
                    <Package className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                    <h3 className="text-xl font-medium text-gray-500">
                      {role === 'CUSTOMER' ? 'Anda belum memiliki riwayat pesanan' : 'Belum ada data order'}
                    </h3>
                    <Button variant="outline" className="mt-4" onClick={() => setActiveTab('add')}>
                      Buat Pesanan Baru
                    </Button>
                  </div>
                )}
              </div>
            </div>
          )}
        </main>
      </div>

      {/* Floating WA Button */}
      <a 
        href={`https://wa.me/6285695014434?text=${encodeURIComponent(whatsappOrderTemplate)}`}
        target="_blank" 
        className="whatsapp-float"
        title="Order via WhatsApp"
      >
        <div className="whatsapp-pulse"></div>
        <MessageCircle className="w-8 h-8" />
        <span className="wa-label">Order via WA</span>
      </a>

      {/* Mobile Navigation */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t flex justify-around p-3 pb-6 z-50">
        {role === 'ADMIN' && <MobileNavButton icon={LayoutDashboard} active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />}
        <MobileNavButton icon={History} active={activeTab === 'orders'} onClick={() => setActiveTab('orders')} />
        <MobileNavButton icon={PlusCircle} active={activeTab === 'add'} onClick={() => setActiveTab('add')} />
        <MobileNavButton icon={LogOut} active={false} onClick={handleLogout} />
      </div>
    </div>
  );
}

// --- Sub-components ---

function SidebarLink({ icon: Icon, label, active, onClick }: any) {
  return (
    <button
      onClick={onClick}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 ${
        active ? 'bg-white text-blue-700 font-bold shadow-md' : 'text-blue-100 hover:bg-white/10'
      }`}
    >
      <Icon className="w-5 h-5" />
      <span>{label}</span>
    </button>
  );
}

function MobileNavButton({ icon: Icon, active, onClick }: any) {
  return (
    <button onClick={onClick} className={`p-2 rounded-xl transition-all ${active ? 'bg-blue-600 text-white scale-110 shadow-lg shadow-blue-200' : 'text-gray-400'}`}>
      <Icon className="w-6 h-6" />
    </button>
  );
}

function StatCard({ label, value, icon: Icon, color }: any) {
  const colors = {
    blue: 'bg-blue-50 text-blue-600',
    green: 'bg-green-50 text-green-600',
    orange: 'bg-orange-50 text-orange-600',
    purple: 'bg-purple-50 text-purple-600'
  };
  return (
    <Card className="flex items-center gap-4 border-none shadow-md shadow-gray-100">
      <div className={`p-4 rounded-2xl ${colors[color as keyof typeof colors]}`}>
        <Icon className="w-6 h-6" />
      </div>
      <div>
        <p className="text-sm text-gray-500 font-medium">{label}</p>
        <p className="text-2xl font-bold">{value}</p>
      </div>
    </Card>
  );
}

function StatusFilter({ current, onClick }: any) {
  return (
    <button onClick={onClick} className={`px-4 py-1.5 rounded-full text-sm font-semibold border ${current ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white text-gray-600 border-gray-200'}`}>
      {current}
    </button>
  );
}

function OrderForm({ role, prefilledPhone, onAdd }: { role: Role, prefilledPhone: string, onAdd: (o: Order, n: boolean) => void }) {
  const [formData, setFormData] = useState({
    customerName: '',
    customerPhone: prefilledPhone || '',
    customerAddress: '',
    weight: 0,
    serviceType: 'Cuci Kering' as ServiceType,
    specialRequest: '',
    deliveryMethod: 'Ambil Sendiri' as any
  });

  useEffect(() => {
    if (prefilledPhone) {
      setFormData(prev => ({ ...prev, customerPhone: prefilledPhone }));
    }
  }, [prefilledPhone]);

  const total = formData.weight * SERVICE_PRICES[formData.serviceType];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newOrder: Order = {
      id: Date.now().toString(),
      notaNumber: generateNotaNumber(),
      ...formData,
      totalPrice: total,
      status: 'Baru',
      createdAt: new Date().toISOString(),
      estimatedFinishDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString(),
    };

    onAdd(newOrder, true);

    const waMessage = `Halo 👋 Terima kasih Kak 🙏
Laundry atas nama ${newOrder.customerName} sudah kami terima.
Layanan: ${newOrder.serviceType}
Berat: ${newOrder.weight}kg
Total sementara: ${formatIDR(newOrder.totalPrice)}
Estimasi selesai: 2 hari.
Kami akan kabari saat sudah selesai ya 😊`;

    sendWhatsAppMessage(newOrder.customerPhone, waMessage);

    setFormData({
      customerName: '',
      customerPhone: prefilledPhone || '',
      customerAddress: '',
      weight: 0,
      serviceType: 'Cuci Kering',
      specialRequest: '',
      deliveryMethod: 'Ambil Sendiri'
    });
  };

  return (
    <div className="max-w-2xl mx-auto">
      <Card>
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-blue-100 rounded-lg">
            <PlusCircle className="text-blue-600" />
          </div>
          <h3 className="text-xl font-bold text-gray-800">Input Order Laundry</h3>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-semibold mb-1 text-gray-700">Nama Pelanggan</label>
              <input 
                required
                type="text" 
                className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-gray-900"
                placeholder="Contoh: Budi Santoso"
                value={formData.customerName}
                onChange={(e) => setFormData({...formData, customerName: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-semibold mb-1 text-gray-700">Nomor HP (WhatsApp)</label>
              <input 
                required
                type="tel" 
                className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-gray-900"
                placeholder="Contoh: 08123456789"
                value={formData.customerPhone}
                readOnly={!!prefilledPhone && role === 'CUSTOMER'}
                onChange={(e) => setFormData({...formData, customerPhone: e.target.value})}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-semibold mb-1 text-gray-700">Alamat</label>
            <input 
              required
              type="text" 
              className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-gray-900"
              placeholder="Contoh: Jl. Melati No. 5"
              value={formData.customerAddress}
              onChange={(e) => setFormData({...formData, customerAddress: e.target.value})}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-semibold mb-1 text-gray-700">Berat (Kg)</label>
              <input 
                required
                type="number" 
                min="0.1"
                step="0.1"
                className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-gray-900"
                value={formData.weight}
                onChange={(e) => setFormData({...formData, weight: parseFloat(e.target.value) || 0})}
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-semibold mb-1 text-gray-700">Pilih Layanan</label>
              <select 
                className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-gray-900"
                value={formData.serviceType}
                onChange={(e) => setFormData({...formData, serviceType: e.target.value as ServiceType})}
              >
                <option value="Cuci Kering">Cuci Kering (Rp 5.000/kg)</option>
                <option value="Cuci Setrika">Cuci Setrika (Rp 7.000/kg)</option>
                <option value="Setrika Saja">Setrika Saja (Rp 4.000/kg)</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
             <div>
              <label className="block text-sm font-semibold mb-1 text-gray-700">Metode Antar/Jemput</label>
              <div className="flex gap-2">
                {['Ambil Sendiri', 'Antar/Jemput'].map(m => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setFormData({...formData, deliveryMethod: m as any})}
                    className={`flex-1 py-2 px-3 rounded-xl border-2 transition-all font-medium text-sm ${formData.deliveryMethod === m ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-gray-200 text-gray-500'}`}
                  >
                    {m}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="block text-sm font-semibold mb-1 text-gray-700">Catatan Khusus (Opsional)</label>
              <input 
                type="text" 
                className="w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-gray-900"
                placeholder="Contoh: Jangan pakai pemutih"
                value={formData.specialRequest}
                onChange={(e) => setFormData({...formData, specialRequest: e.target.value})}
              />
            </div>
          </div>

          <div className="mt-6 p-4 bg-gray-50 rounded-2xl flex items-center justify-between border-2 border-dashed border-gray-200">
            <div>
              <p className="text-gray-500 text-sm font-medium">Estimasi Biaya</p>
              <p className="text-3xl font-bold text-blue-600">{formatIDR(total)}</p>
            </div>
            <Button type="submit" disabled={total <= 0}>
              <PlusCircle /> Buat Pesanan
            </Button>
          </div>
        </form>
      </Card>
    </div>
  );
}

function OrderCard({ order, isAdmin, onUpdateStatus }: { order: Order, isAdmin: boolean, onUpdateStatus: (id: string, s: OrderStatus) => void }) {

  const generatePDF = async () => {
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: [80, 150] 
    });

    const margin = 5;
    const pageWidth = 80;
    let y = 10;

    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text("LAUNDRY IBU TINI", pageWidth / 2, y, { align: "center" });
    y += 5;
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text("Bersih • Wangi • Rapi", pageWidth / 2, y, { align: "center" });
    y += 5;
    doc.text("==============================", pageWidth / 2, y, { align: "center" });
    y += 7;

    const drawLine = (label: string, value: string) => {
      doc.text(label, margin, y);
      doc.text(value, pageWidth - margin, y, { align: "right" });
      y += 5;
    };

    doc.setFont("helvetica", "bold");
    drawLine("No Nota:", order.notaNumber);
    doc.setFont("helvetica", "normal");
    drawLine("Tanggal:", new Date(order.createdAt).toLocaleDateString());
    drawLine("Nama:", order.customerName);
    drawLine("Telepon:", order.customerPhone);
    y += 2;
    doc.text("------------------------------", pageWidth / 2, y, { align: "center" });
    y += 5;
    drawLine("Layanan:", order.serviceType);
    drawLine("Berat:", `${order.weight} Kg`);
    drawLine("Harga/kg:", formatIDR(SERVICE_PRICES[order.serviceType]));
    y += 2;
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    drawLine("TOTAL:", formatIDR(order.totalPrice));
    y += 5;
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    drawLine("Estimasi Selesai:", new Date(order.estimatedFinishDate).toLocaleDateString());
    y += 10;
    doc.text("Terima kasih telah", pageWidth / 2, y, { align: "center" });
    y += 4;
    doc.text("menggunakan jasa kami 🙏", pageWidth / 2, y, { align: "center" });

    doc.save(`Nota_${order.notaNumber}.pdf`);
  };

  const handleFinishNotify = () => {
    const msg = `Halo Kak 👋
Laundry atas nama ${order.customerName} sudah SELESAI ✅
Total pembayaran: ${formatIDR(order.totalPrice)}
Bisa diambil atau kami antar ya 🚚😊`;
    sendWhatsAppMessage(order.customerPhone, msg);
    onUpdateStatus(order.id, 'Selesai');
  };

  const statusColors = {
    'Baru': 'bg-blue-100 text-blue-700',
    'Proses': 'bg-orange-100 text-orange-700',
    'Selesai': 'bg-green-100 text-green-700'
  };

  return (
    <Card className="hover:shadow-md transition-all duration-300 relative border-l-4 border-l-blue-500 shadow-sm shadow-gray-100">
      <div className="flex justify-between items-start mb-4">
        <div>
          <p className="text-xs font-bold text-gray-400 uppercase tracking-tighter">{order.notaNumber}</p>
          <h4 className="text-lg font-bold text-gray-800">{order.customerName}</h4>
        </div>
        <span className={`px-3 py-1 rounded-full text-xs font-bold ${statusColors[order.status]}`}>
          {order.status}
        </span>
      </div>

      <div className="space-y-2 mb-6">
        <div className="flex items-center gap-2 text-sm text-gray-600">
          <Package className="w-4 h-4 text-blue-500" />
          <span className="text-gray-700">{order.serviceType} • {order.weight}kg</span>
        </div>
        <div className="flex items-center gap-2 text-sm text-gray-600">
          <Clock className="w-4 h-4 text-orange-500" />
          <span className="text-gray-700">Selesai: {new Date(order.estimatedFinishDate).toLocaleDateString()}</span>
        </div>
        <div className="flex items-center gap-2 text-sm text-gray-600">
          <Phone className="w-4 h-4 text-green-500" />
          <span className="text-gray-700">{order.customerPhone}</span>
        </div>
      </div>

      <div className="pt-4 border-t border-gray-100 flex items-center justify-between mb-4">
        <p className="text-sm text-gray-500 font-medium">Tagihan</p>
        <p className="text-xl font-bold text-blue-600">{formatIDR(order.totalPrice)}</p>
      </div>

      <div className="grid grid-cols-2 gap-2">
        <button 
          onClick={generatePDF}
          className="flex items-center justify-center gap-2 bg-gray-50 hover:bg-gray-100 text-gray-700 p-2 rounded-xl transition-all border border-gray-200"
        >
          <Printer className="w-4 h-4" /> Nota
        </button>

        {isAdmin ? (
          <>
            {order.status === 'Baru' && (
              <button 
                onClick={() => onUpdateStatus(order.id, 'Proses')}
                className="bg-orange-600 hover:bg-orange-700 text-white p-2 rounded-xl transition-all font-semibold"
              >
                Proses
              </button>
            )}
            {order.status === 'Proses' && (
              <button 
                onClick={handleFinishNotify}
                className="bg-green-600 hover:bg-green-700 text-white p-2 rounded-xl transition-all font-semibold"
              >
                Selesaikan
              </button>
            )}
            {order.status === 'Selesai' && (
              <div className="flex items-center justify-center gap-1 text-green-600 font-bold text-sm bg-green-50 rounded-xl">
                <CheckCircle2 className="w-4 h-4" /> Selesai
              </div>
            )}
          </>
        ) : (
          <div className="flex items-center justify-center text-gray-400 font-medium text-xs text-center leading-tight bg-gray-50 rounded-xl px-1">
            Riwayat Pesanan Aktif
          </div>
        )}
      </div>
    </Card>
  );
}
